package com.movieticket.user; import jakarta.persistence.*; @Entity @Table(name="users",uniqueConstraints=@UniqueConstraint(columnNames="email")) public class User {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String email;@Column(nullable=false) private String password;@Column(nullable=false) private String role="USER";public User(){}public User(String e,String p){email=e;password=p;}public Long getId(){return id;}public String getEmail(){return email;}public String getPassword(){return password;}public String getRole(){return role;}}
